const RPC='https://rpc.mainnet.chain.robinhood.com';
const rpc=(m,p)=>fetch(RPC,{method:'POST',headers:{'Content-Type':'application/json','User-Agent':'Mozilla/5.0'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:m,params:p})}).then(r=>r.json()).then(d=>d.result);
function disasm(code){
  const bytes=Buffer.from(code.replace(/^0x/,''),'hex');
  const ops=[];
  for(let i=0;i<bytes.length;i++){
    const op=bytes[i];
    if(op>=0x60&&op<=0x7f){const n=op-0x5f;ops.push({pc:i,op:'PUSH'+n,data:bytes.slice(i+1,i+1+n).toString('hex')});i+=n;continue;}
    ops.push({pc:i,op:op.toString(16)});
  }
  return ops;
}
(async()=>{
  const code=await rpc('eth_getCode',['0x7d5b49859fc151c764e6fbac938c1bf4a0fe6991','latest']);
